def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    # Isolated single-cell speckles are restored from the surrounding pattern.
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = [(r, c)]
            seen.add((r, c))
            component = []
            while q:
                y, x = q.pop()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if len(component) != 1:
                continue

            # Prefer the color that completes a 2x2 solid patch.
            completions = Counter()
            for y0 in (r - 1, r):
                for x0 in (c - 1, c):
                    cells = [(y, x) for y in (y0, y0 + 1) for x in (x0, x0 + 1)]
                    if all(0 <= y < h and 0 <= x < w for y, x in cells):
                        vals = [grid[y][x] for y, x in cells if (y, x) != (r, c)]
                        if len(set(vals)) == 1:
                            completions[vals[0]] += 1
            if completions:
                replacement = completions.most_common(1)[0][0]
            else:
                neighbors = [grid[y][x]
                             for y in range(max(0, r - 1), min(h, r + 2))
                             for x in range(max(0, c - 1), min(w, c + 2))
                             if (y, x) != (r, c)]
                if not neighbors:
                    continue
                replacement = Counter(neighbors).most_common(1)[0][0]
            out[r][c] = replacement
    return out
